# filename: app/services/event_publisher.py
# Code Generated by Sidekick is for learning and experimentation purposes only.

import json
import aio_pika
from typing import Dict, Any
from app.core.logging import get_logger
from app.config import settings
from app.models.booking import Booking

logger = get_logger(__name__)


class EventPublisher:
    def __init__(self):
        self.connection = None
        self.channel = None
        self.exchange = None

    async def connect(self):
        """Establish RabbitMQ connection"""
        try:
            self.connection = await aio_pika.connect_robust(
                settings.RABBITMQ_URL
            )
            self.channel = await self.connection.channel()
            self.exchange = await self.channel.declare_exchange(
                settings.RABBITMQ_EXCHANGE,
                aio_pika.ExchangeType.TOPIC,
                durable=True
            )
            logger.info("RabbitMQ connection established")
        except Exception as e:
            logger.error(f"Failed to connect to RabbitMQ: {e}")
            raise

    async def close(self):
        """Close RabbitMQ connection"""
        if self.connection:
            await self.connection.close()

    async def publish_booking_created(self, booking: Booking):
        """Publish booking created event"""
        event_data = {
            "event_type": "booking.created",
            "booking_id": str(booking.booking_id),
            "user_id": str(booking.user_id),
            "event_id": str(booking.event_id),
            "seat_id": str(booking.seat_id),
            "amount": float(booking.total_amount),
            "status": booking.booking_status.value,
            "timestamp": booking.created_at.isoformat()
        }

        await self._publish("booking.created", event_data)

    async def _publish(self, routing_key: str, data: Dict[str, Any]):
        """Publish message to RabbitMQ"""
        if not self.exchange:
            logger.warning("RabbitMQ not connected, skipping event publish")
            return

        try:
            message = aio_pika.Message(
                body=json.dumps(data).encode(),
                content_type="application/json",
                delivery_mode=aio_pika.DeliveryMode.PERSISTENT
            )

            await self.exchange.publish(
                message,
                routing_key=routing_key
            )

            logger.debug(f"Event published: {routing_key}", extra={"data": data})

        except Exception as e:
            logger.error(f"Failed to publish event: {e}", exc_info=True)
